GimCorpus.put(430,0,[[1,3,"המור הוא הדם הצרור. א\"א אין דעתי מקבלת שיכנסו במעשה הקדש דם שום חיה בעולם כל שכן דם חיה טמאה אבל המור הוא האמור בשיר השירים באתי לגני אחותי כלה אריתי מורי עם בשמי והוא ממין עשב או ממין אילן וריחו נודף:",1,0],[1,10,"והוא שיסוך ממנו בכזית. א\"א לא מחוור מתוך הגמרא דכריתות דבעינן לסיכה כזית אלא לנתינה בלבד כדעת ר\"י:",1,0],[3,11,"אבל כהן שעבד עבודת לוי. א\"א והלא כבר נאמר ולא ימותו גם הם גם אתם ובספרי נמי הכי דריש ליה לעונש ואזהרה:",1,0],[4,7,"ועבודתו לאותו הכהן. א\"א לא כי אלא אכילתו ועורו של בעליו:",1,0],[4,9,"נותנו לבעלי מומין טהורין. א\"א כל זה שבוש אלא נותנו לכל כהן שירצה לעבדה ועורה ואכילתה לבעלי מומין טהורין שבאותו משמר:",1,0],[4,13,"ואם עבד קודם. א\"א נראה מדבריו ימים שהיה בהם המשיחה לא היה עובד ואין זה מן החכמה אלא כשאמרו נתרבה שבעה ונמשח שבעה דבעינן שבעה לכתחלה ה\"מ לעבודת יה\"כ אבל לעבודת אותן הימים בכל יום עובד בשמונה בגדים:",1,0],[5,6,"עד שיראה כאילו הוא צמח. א\"א איני מבין המופת הזה אבל אני אומר ראש שער העליון יורד עד עיקרו של תחתון וגוזז את התחתון עד עיקרו שלא ירד מראשו של עליון ולמטה כדי שיהא מצחו ופדחתו מגולה:",1,0],[5,15,"ואינו נכנס לעזרה. א\"א זהו טעות גדולה שלא אמרו דבר זה במשנה אלא על לוי קטן שאינו ראוי לעבודתו אלא לשיר ומסניפין לאחיו הגדולים מפני שקולן דק ונותנין תבל בנעימה ואין עולין מן החשבון:",1,0],[6,4,"והיא יתירה להן. א\"א איני יודע מהו שאמר והיא יתרה להן שאיני מוצאה אלא ביום שיש בו מוסף והיא יתירה לכל ישראל ואינה בכל יום והוא אומר בכל יום משבת שהוא מעמדן מתפללין ד' תפלות:",1,0],[6,4,"ובתפלה השניה. א\"א זו התפלה השניה שאמר אם תפלת המוסף הוא כמו שאנו סוברים למה אמר שקורים בה ג' אנשים והלא במוסף קורין ד' אלא שהרביעי קורא בענינו של יום:",2,0],[6,8,"ובתפלה שניה. א\"א הראה דעתו בכאן על אותה תפלה שניה שאמר שאינה תפלת מוסף שאם היה תפלת מוסף הרי המוסף דוחה של מוסף ושל מנחה כחזרתו של ר\"ע סוף דבר אין דבריו מכוונים לעיקר ההלכה:",1,0],[7,1,"אחד על הזמנים וכו' עד על מעשה בגדי כהונה. א\"א ולמה לא מנה הממונה על הפקיע והוא מכין הפתילות:",1,0],[7,9,"משלשים יום לשלשים יום וכו'. א\"א לא כי הממונה על הקינין ועל הנסכים אינו אלא גזברות בעלמא וכל מי שהוא חייב קינין מביא לידו או הקינין בעצמו או דמיו ונותנן לשופר והוא משתדל להקריבן ואינו מתעצל וכן על הנסכים היה איש ממונה ולוקח במעות של תרומת הלשכה יינות שמנים וסלתות מבעלי בתים ועל אותו בעל הבית המוכר אמרו אם קבל לספק מארבע ועמדו משלש או משלש ועמדו מארבע מספק מארבע וכל מחוייב נסכים מביא מעות ולוקח מזה הממונה ואם יש לו ריוח בזה הוא הנקרא מותר נסכים ועושין ממנו לקיץ למזבח ואע\"פ שאמרו אין משתכרין בשל הקדש הני מילי פירות שהוא כעין הגנות והוא דרך עניות אבל נסכים שהן צרכי ציבור לוקחין ואם הותירו מוכרין ליחידים מכ\"מ הממונים לא מרויחין ולא מפסידין לעצמן כלום:",1,0],[7,12,"עד שיוקרו הנסכים. א\"א לא כי אלא שמא יעשנו אובד ויביא לידי אחר ויוציא חותמו:",1,0],[7,20,"ומתחת ידו נעשה. א\"א אומר אני שהוא פינחס המלביש:",1,0],[8,2,"ולפיכך נקראת מגבעת. א\"א אני אומר אין מעשהו של זה כמעשהו של זה מצנפת ארוך הרבה וכורך אותו כריכות הרבה ככריכות הישמעאלים אבל מעשה המגבעות כעין הכובעין שלנו חדין מלמעלה והן קצרין:",1,0],[8,12,"אסור לכהן הדיוט. א\"א לא מחוור מן הגמרא הכי אלא כל היום מותר במקדש:",1,0],[8,13,"הארגמן הוא הצמר. א\"א לי נראה ארגמן ארוג משני מינין או משלשה צבעין על כן נקרא ארגמן:",1,0],[9,2,"חופר את האותיות. א\"א אינו חופר אלא מכה בדפוס צורת האותיות מאחריו עד שהאותיות בולטות מלפניו ומדובק בשעוה שאמר אינו כלום:",1,0],[9,2,"כדי שיהא נקשר בפתיל. א\"א עוד יש בו נקב באמצע שמכניס בו פתיל תכלת וכורכו על המצנפת וקושרו עם הפתיל שבראשו שהוא קשור לו כנגד ערפו:",2,0],[9,3,"ואין לו בית יד. א\"א זו מנין לו:",1,0],[9,3,"אלא נחלק. א\"א וגם זו מנין לו:",2,0],[9,11,"וחשב האפוד קשור על לבו. א\"א הפליג לעלות ואינו אלא למטה מטיבורו:",1,0],[10,9,"והוא שלא יחוץ הגמי. א\"א דבריו סותרים זה את זה הלא אמר שלא במקום בגדים פחות משלש אינו חוצץ בין היד לכלי וכן הוא בעירובין ובזבחים:",1,0]]);
